using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Globalization;using Nini.Ini;
class FaultReader:TextReader{
 StringReader inner;List<string> trace;int point,nth,seen;
 public FaultReader(string text,List<string> log,int p,int n){inner=new(text);trace=log;point=p;nth=n;}
 void Hit(int p,string name){trace.Add(name);if(point==p&&++seen==nth)throw new Exception("fault");}
 public override int Peek(){Hit(1,"P");return inner.Peek();}public override int Read(){Hit(2,"R");return inner.Read();}public override void Close(){Hit(3,"C");inner.Close();}
}
static class Program{
 static string Decode(string text){if(text=="-")return null;if(text==".")return "";var b=Convert.FromHexString(text);var chars=new char[b.Length/2];for(int i=0;i<chars.Length;++i)chars[i]=(char)(b[2*i]|b[2*i+1]<<8);return new(chars);}
 static string Hex(string text){if(text==null)return "-";if(text.Length==0)return ".";var b=new byte[text.Length*2];for(int i=0;i<text.Length;++i){b[2*i]=(byte)text[i];b[2*i+1]=(byte)(text[i]>>8);}return Convert.ToHexString(b).ToLowerInvariant();}
 static string Error(Exception e)=>e==null?"-":e.GetType().FullName+":"+unchecked((uint)e.HResult)+":"+Hex(e.Message)+":"+(e is IniException ini?ini.LineNumber:0)+":"+(e is IniException ini2?ini2.LinePosition:0);
 static string Run(string line){var p=line.Split(' ');int flags=int.Parse(p[1]);var trace=new List<string>();var text=Decode(p[0]);var reader=new IniReader(text==null?null:new FaultReader(text,trace,int.Parse(p[2]),int.Parse(p[3])));GC.SuppressFinalize(reader);reader.IgnoreComments=(flags&1)!=0;reader.LineContinuation=(flags&2)!=0;reader.AcceptCommentAfterKey=(flags&4)!=0;reader.AcceptNoAssignmentOperator=(flags&8)!=0;reader.ConsumeAllKeyText=(flags&16)!=0;char[] comments=null,assign=null;Exception saved=null;var output=new StringBuilder();
 foreach(var op in p[4].Split(',')){string result=op;try{switch(op){case "r":result=reader.Read()?"1":"0";break;case "s":result=reader.MoveToNextSection()?"1":"0";break;case "k":result=reader.MoveToNextKey()?"1":"0";break;case "c":reader.Close();break;case "d":reader.Dispose();break;case "q":result=Error(saved);break;case "gc":var c=reader.GetCommentDelimiters();result=Hex(new(c));if(c.Length>0)c[0]='!';break;case "ga":var a=reader.GetAssignDelimiters();result=Hex(new(a));if(a.Length>0)a[0]='!';break;case "mc":if(comments!=null&&comments.Length>0)comments[0]='#';break;case "ma":if(assign!=null&&assign.Length>0)assign[0]=':';break;default:if(op.StartsWith("sc")){comments=Decode(op.Substring(2))?.ToCharArray();reader.SetCommentDelimiters(comments);}else if(op.StartsWith("sa")){assign=Decode(op.Substring(2))?.ToCharArray();reader.SetAssignDelimiters(assign);}else if(op.Length==2){bool value=op[1]=='1';switch(op[0]){case 'i':reader.IgnoreComments=value;break;case 'l':reader.LineContinuation=value;break;case 't':reader.AcceptCommentAfterKey=value;break;case 'a':reader.AcceptNoAssignmentOperator=value;break;case 'v':reader.ConsumeAllKeyText=value;break;default:throw new Exception("operation");}}else throw new Exception("operation");break;}}catch(Exception e){saved=e;result="EX:"+Error(saved);}
 int bits=(reader.IgnoreComments?1:0)|(reader.LineContinuation?2:0)|(reader.AcceptCommentAfterKey?4:0)|(reader.AcceptNoAssignmentOperator?8:0)|(reader.ConsumeAllKeyText?16:0);if(output.Length>0)output.Append('|');output.Append(result+"/"+(int)reader.Type+","+(int)reader.ReadState+","+reader.LineNumber+","+reader.LinePosition+","+Hex(reader.Name)+","+Hex(reader.Value)+","+Hex(reader.Comment)+","+Hex(new(reader.GetCommentDelimiters()))+","+Hex(new(reader.GetAssignDelimiters()))+","+bits+"/"+Error(saved));}
 return output+"/IO:"+string.Join("",trace);}
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;CultureInfo.CurrentUICulture=CultureInfo.InvariantCulture;Console.OutputEncoding=new UTF8Encoding(false);for(string line;(line=Console.ReadLine())!=null;)Console.WriteLine(Run(line));}
}
